  ('departamento-nunoa-plaza-nunoa', 'departamento', 'venta', 'Ñuñoa', 'Sector Plaza Ñuñoa', 6450, 'UF', NULL, 2, 2, 1, 1, 78, 85, NULL, 5, 'Oriente', 2019, 140000, '["Precio revisado"]', 'Dos dormitorios en suite, cerca de Plaza Ñuñoa, parques y la futura línea 7 del metro.', '["Departamento moderno con dos dormitorios en suite, ideal para pareja o inversión. Living con salida a balcón y cocina americana con isla.","Ubicado a pasos de Plaza Ñuñoa, con comercio, restaurantes y áreas verdes en un radio de 10 minutos a pie."]', '["Dos dormitorios en suite","Cocina con isla","Balcón","Quincho y sala multiuso","Bicicletero","Lavandería en el edificio"]', 1, '2026-10-28', 'PUBLICADA', 7, 'atardecer'),
  ('departamento-las-condes-el-golf', 'departamento', 'venta', 'Las Condes', 'Sector El Golf', 15900, 'UF', NULL, 3, 3, 2, 1, 148, 166, NULL, 12, 'Norte', 2014, 320000, '["Con informe de valor"]', 'Piso alto con orientación norte, terraza amplia y dos estacionamientos en el corazón de El Golf.', '["Departamento de 148 m² útiles en piso 12, con orientación norte y terraza de 18 m². Dormitorio principal con walk-in closet y baño en suite.","Edificio con conserjería, piscina temperada y salas de reuniones, a pasos de Isidora Goyenechea y del metro El Golf."]', '["Terraza de 18 m²","Walk-in closet","Piscina temperada","Gimnasio","Salas de reuniones","Dos estacionamientos","Calefacción por losa radiante"]', 1, '2026-10-21', 'PUBLICADA', 11, 'dia'),
  ('casa-la-reina-principe-de-gales', 'casa', 'venta', 'La Reina', 'Sector Príncipe de Gales', 21500, 'UF', NULL, 5, 4, 3, 1, 240, 260, 720, NULL, 'Norte', 2008, NULL, '["Jardín consolidado"]', 'Casa familiar de dos pisos con jardín consolidado, piscina y vista a la precordillera.', '["Casa de dos pisos en terreno de 720 m², con living y comedor independientes, escritorio y sala de estar familiar en el segundo nivel.","Jardín consolidado con árboles nativos, piscina y quincho techado. Barrio residencial tranquilo, cerca de colegios y de Avenida Príncipe de Gales."]', '["Terreno de 720 m²","Piscina","Quincho techado","Escritorio","Pieza y baño de servicio","Riego automático","Paneles solares"]', 1, '2026-10-14', 'PUBLICADA', 5, 'dia'),
  ('departamento-vitacura-arriendo', 'departamento', 'arriendo', 'Vitacura', 'Sector Alonso de Córdova', 1650000, 'CLP', 'mes', 3, 3, 2, 1, 132, 150, NULL, 6, 'Nororiente', 2017, 290000, '["Disponible de inmediato"]', 'Departamento amplio y silencioso, a pasos de Alonso de Córdova y del Parque Bicentenario.', '["Departamento de 132 m² útiles con living amplio, terraza techada y cocina cerrada con comedor de diario.","Edificio de baja densidad a pasos de Alonso de Córdova, con fácil acceso a Costanera Norte y al Parque Bicentenario."]', '["Terraza techada","Comedor de diario","Edificio de baja densidad","Piscina","Dos estacionamientos","Acepta mascotas"]', 1, '2026-11-06', 'PUBLICADA', 9, 'atardecer'),
  ('departamento-providencia-manuel-montt-arriendo', 'departamento', 'arriendo', 'Providencia', 'Sector Manuel Montt', 890000, 'CLP', 'mes', 2, 2, 1, 0, 64, 70, NULL, 10, 'Poniente', 2020, 115000, '["Cerca del metro"]', 'Dos dormitorios a dos cuadras del metro Manuel Montt, con balcón y estacionamiento.', '["Departamento de dos dormitorios y dos baños, con living iluminado y balcón. Cocina equipada con encimera vitrocerámica.","A dos cuadras del metro Manuel Montt, con supermercados, cafés y servicios a la mano."]', '["Balcón","Cocina equipada","Estacionamiento","Gimnasio","Cowork en el edificio","Bicicletero"]', 1, '2026-11-08', 'PUBLICADA', 13, 'dia'),
  ('oficina-las-condes-isidora-goyenechea', 'oficina', 'arriendo', 'Las Condes', 'Sector Isidora Goyenechea', 62, 'UF', 'mes', 0, 2, 2, 1, 85, 92, NULL, 14, 'Norte', 2012, 210000, '["Habilitada"]', 'Oficina habilitada en piso 14, con sala de reuniones, dos baños y dos estacionamientos.', '["Oficina habilitada de 85 m² útiles con planta libre, sala de reuniones vidriada, kitchenette y dos baños.","Edificio corporativo con control de acceso, a pasos de Isidora Goyenechea y del metro Tobalaba."]', '["Planta libre habilitada","Sala de reuniones","Kitchenette","Aire acondicionado","Control de acceso","Dos estacionamientos"]', 0, '2026-10-30', 'PUBLICADA', 17, 'dia'),
  ('casa-lo-barnechea-la-dehesa', 'casa', 'venta', 'Lo Barnechea', 'Sector La Dehesa', 28900, 'UF', NULL, 5, 5, 4, 2, 320, 345, 1200, NULL, 'Nororiente', 2015, NULL, '["Vista a la cordillera"]', 'Casa contemporánea con vista a la cordillera, piscina y terreno de 1.200 m² en condominio.', '["Casa contemporánea de 320 m² en condominio con seguridad, con grandes ventanales hacia el jardín y vista a la cordillera.","Primer piso con living, comedor y cocina integrados; segundo piso con cinco dormitorios, cuatro de ellos en suite."]', '["Terreno de 1.200 m²","Condominio con seguridad","Piscina","Sala de juegos","Bodegas","Calefacción por losa radiante"]', 0, '2026-10-09', 'PUBLICADA', 21, 'atardecer');
